mapper.insert:
SELECT NVL(MAX(A.TASKWK_RPT_SN), 0) +1 AS TASKWK_RPT_SN FROM AFA210 A WHERE A.RESRCE_NO = #{RESRCE_NO}
/* insertOperRpt - Lee SangHoon */
INSERT INTO AFA210( /* 업무보고 */ RESRCE_NO, /* 자원번호 */ TASKWK_RPT_SN, /* 업무보고일련번호 */ RPT_SE_CD, /* 보고구분코드 */ PRD_BGNG_YMD, /* 기간시작일자 */ PRD_END_YMD, /* 기간종료일자 */ TTL_NM, /* 제목명 */ RPT_CN, /* 보고내용 */ ATFINO, /* 첨부파일번호 */ APLY_YMD, /* 신청일자 */ APLY_PIC_NO, /* 신청담당자번호 */ APRV_STTS_SE_CD, /* 승인상태구분코드 */ DEL_YN, /* 삭제여부 */ FRST_RGTR_ID, /* 최초등록자아이디 */ LAST_MDFR_ID) /* 최종수정자아이디 */ VALUES( #{RESRCE_NO}, #{TASKWK_RPT_SN}, #{RPT_SE_CD}, #{PRD_BGNG_YMD}, #{PRD_END_YMD}, #{TTL_NM}, #{RPT_CN}, #{ATFINO}, TO_CHAR(SYSDATE,'YYYYMMDD'), #{APLY_PIC_NO}, #{APRV_STTS_SE_CD}, 'N', #{FRST_RGTR_ID}, #{LAST_MDFR_ID})

mapper.update:
/* updateOperRpt - Lee SangHoon */
UPDATE AFA210 SET /* 업무보고 */
PRD_BGNG_YMD = #{PRD_BGNG_YMD}, /* 기간시작일자 */ PRD_END_YMD = #{PRD_END_YMD}, /* 기간종료일자 */ TTL_NM = #{TTL_NM}, /* 제목명 */ RPT_CN = #{RPT_CN}, /* 보고내용 */ ATFINO = #{ATFINO}, /* 첨부파일번호 */ LAST_MDFR_ID = #{LAST_MDFR_ID}, /* 최종수정자아이디 */ LAST_MDFCN_DT = SYSDATE /* 최종수정일시 */
,APRV_STTS_SE_CD = #{APRV_STTS_SE_CD} /* 승인상태구분코드 */ ,RJCT_CS_CN = #{RJCT_CS_CN} /* 반려사유내용 */
,PRCS_YMD = TO_CHAR(SYSDATE,'YYYYMMDD') /* 처리일자 */ ,APRV_PIC_NO = #{APRV_PIC_NO} /* 승인담당자번호 */
WHERE 1=1 AND RESRCE_NO = #{RESRCE_NO__origin} AND RPT_SE_CD = #{RPT_SE_CD__origin} AND TASKWK_RPT_SN = #{TASKWK_RPT_SN__origin}


/* deleteOperRpt - Lee SangHoon */

UPDATE AFA210 SET       /* 업무보고 */

    DEL_YN = 'Y',       /* 삭제여부 */
    LAST_MDFR_ID = #{LAST_MDFR_ID},     /* 최종수정자아이디 */
    LAST_MDFCN_DT = SYSDATE     /* 최종수정일시 */

WHERE 1=1
AND RESRCE_NO = #{RESRCE_NO__origin}
AND RPT_SE_CD = #{RPT_SE_CD__origin}
AND TASKWK_RPT_SN = #{TASKWK_RPT_SN__origin}
